// Assessment panel for the Paths page (D-026): one table per fork, read from
// AutoGenerated/option_assessment.json. Independent of pm-paths-page.js.
(function () {
  'use strict';

  var URL = '../AutoGenerated/option_assessment.json';

  function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text !== undefined && text !== null) e.textContent = String(text);
    return e;
  }

  function signed(v, digits) {
    if (v === null || v === undefined) return 'OPEN';
    var n = Number(v);
    var t = digits === undefined ? String(n) : n.toFixed(digits);
    return n > 0 ? '+' + t : t;
  }

  function share(r) {
    if (!r) return '-';
    if (r.share_after === null || r.share_after === undefined) return 'none changed';
    return Math.round(r.share_after * 100) + '% (' + signed(r.d_share * 100, 1) + ' pts)';
  }

  function guardText(g) {
    if (!g) return '-';
    if (g.state === 'FIT_AT_24') return 'fit at 24 (' + g.fit_at_24.length + ')';
    return g.state;
  }

  function candText(a) {
    if (a.candidate) return 'candidate';
    return a.provisional ? 'provisional' : 'no';
  }

  function cells(a) {
    var p = a.P || {}, adj = a.P_adjusted || {};
    var chi = adj.d_chi2 === undefined ? p.d_chi2 : adj.d_chi2;
    var lit = a.E ? a.E.literals : null;
    return [
      a.option, p.state || '-',
      p.state === 'COMPUTED' ? signed(adj.d_pass) : '-',
      p.state === 'COMPUTED' ? signed(adj.d_fail) : '-',
      p.state === 'COMPUTED' ? (chi === null ? 'OPEN' : signed(chi, 1)) : '-',
      share(a.R),
      a.E ? signed(a.E.d_free) + (lit === 'OPEN' ? ' (literals OPEN)' : '') : '-',
      a.T === undefined ? '-' : (a.T ? 'yes' : 'no'),
      guardText(a.guard), candText(a)
    ];
  }

  function row(a) {
    var tr = el('tr', a.candidate ? 'pp-cand' : '');
    cells(a).forEach(function (c, i) {
      var td = el('td', c.indexOf('fit at 24') === 0 && i === 8 ? 'pp-fit' : '', c);
      if (i === 0 && a.reasons) td.title = a.reasons.join('; ');
      tr.appendChild(td);
    });
    return tr;
  }

  var HEAD = ['Option', 'State', 'Δpass', 'Δfail', 'Δχ²', 'Provable share',
              'ΔE (free)', 'T', 'Guard', 'Candidate'];

  function forkTable(id, fork) {
    var box = el('div', 'pp-assess-fork');
    box.appendChild(el('h3', '', id + ' (active: ' + fork.active + ')'));
    var wrap = el('div', 'pp-assess-scroll');
    var table = el('table', 'pp-table');
    var hr = el('tr');
    HEAD.forEach(function (h) { hr.appendChild(el('th', '', h)); });
    table.appendChild(hr);
    fork.alternatives.forEach(function (a) { table.appendChild(row(a)); });
    wrap.appendChild(table);
    box.appendChild(wrap);
    return box;
  }

  function render(body, doc) {
    var note = doc.audit === 'OPEN'
      ? 'The formula audit is not published: the guard and the literal counts are OPEN, so no flag below is final.'
      : 'Guard from the formula audit.';
    body.appendChild(el('p', 'pp-quiet', note));
    Object.keys(doc.forks).forEach(function (id) {
      if (doc.forks[id].alternatives.length) body.appendChild(forkTable(id, doc.forks[id]));
    });
  }

  function boot() {
    var body = document.getElementById('pp-assess-body');
    if (!body) return;
    fetch(URL).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.json();
    }).then(function (doc) { render(body, doc); })
      .catch(function () {
        body.appendChild(el('p', 'pp-quiet', 'The assessment (option_assessment.json) is not published yet.'));
      });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
